import{o as r,c as n,a0 as s,j as a,t,p as l}from"./chunks/framework.L_oL6aia.js";const d={class:"rock-copy-email-wrapper inline"},g=JSON.parse('{"title":"Midnight Rambler: Manual de Usuario","description":"","frontmatter":{},"headers":[],"relativePath":"es/midnight-rambler.md","filePath":"es/midnight-rambler.md"}'),c={name:"es/midnight-rambler.md"},b=Object.assign(c,{setup(u){const o=l("Copiar Correo");function i(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="¡Copiado!",setTimeout(function(){o.value="Copiar Correo"},2e3)}return(m,e)=>(r(),n("div",null,[e[1]||(e[1]=s('<h1 id="midnight-rambler-manual-de-usuario" tabindex="-1">Midnight Rambler: Manual de Usuario <a class="header-anchor" href="#midnight-rambler-manual-de-usuario" aria-label="Permalink to &quot;Midnight Rambler: Manual de Usuario&quot;">​</a></h1><p><strong>Stompbox Series #01 · Simulación de Amplificador Neural</strong></p><img src="/midnight.png" alt="Midnight Rambler GUI" style="max-height:280px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><hr><h2 id="_1-el-alma-del-tweed-5e3-una-leyenda-de-estudio" tabindex="-1">1. El Alma del Tweed 5E3: Una Leyenda de Estudio <a class="header-anchor" href="#_1-el-alma-del-tweed-5e3-una-leyenda-de-estudio" aria-label="Permalink to &quot;1. El Alma del Tweed 5E3: Una Leyenda de Estudio&quot;">​</a></h2><p>El <strong>Fender Tweed Deluxe 5E3</strong> (década de 1950) es universalmente reconocido por productores y guitarristas como el amplificador de grabación más venerado en la historia del rock. Su diseño purista a válvulas 6V6 produce una compresión orgánica inconfundible, armónicos cálidos y una respuesta dinámica al toque que los grandes amplificadores de escenario no pueden igualar.</p><p>Desde el crujido rítmico de Keith Richards en los discos clásicos de los Rolling Stones (<em>Sticky Fingers</em>, <em>Exile on Main St.</em>) y la furia de Neil Young, hasta la mordida de Billy Gibbons y las guitarras legendarias de <em>Hotel California</em>, el 5E3 definió generaciones de discos inolvidables.</p><h3 id="por-que-midnight-rambler-marca-la-diferencia" tabindex="-1">Por qué Midnight Rambler Marca la Diferencia <a class="header-anchor" href="#por-que-midnight-rambler-marca-la-diferencia" aria-label="Permalink to &quot;Por qué Midnight Rambler Marca la Diferencia&quot;">​</a></h3><p>A diferencia de las respuestas a impulsos estáticas o los plugins de modelado digital genéricos que se sienten rígidos o artificiales, Midnight Rambler captura la respiración y la respuesta física de un Tweed 5E3 boutique de primera línea:</p><ul><li><strong>Dinámica Neuronal Auténtica:</strong> Impulsado por redes neuronales de aprendizaje profundo NAM (<em>Neural Amp Modeler</em>), reacciona de manera orgánica al potenciómetro de volumen de la guitarra y a la dinámica de tu mano.</li><li><strong>Protección Inteligente y Supresión de Ruido:</strong> Incorpora un Noise Gate adaptativo (-58 dBFS) y un limitador analógico Waveshaper suave pre-NAM (-0.1 dBFS) que garantizan una señal impecable sin zumbidos de fondo.</li><li><strong>Suite de Estudio Lista para Mezcla (<em>Mix-Ready</em>):</strong> Filtros State-Variable TPT independientes post-amplificador (Bass HP y Tone LP) combinados con convolución a latencia cero de gabinete Oxford 12&quot; de 1971 (cinta Royer R121 y dinámico Shure SM57).</li><li><strong>Cero Latencia y 100% Gratuito:</strong> Sin cuentas, sin llaves de protección y con consumo ultra bajo de CPU. Enchufa tu guitarra, sube el volumen y suena a disco clásico desde el primer acorde.</li></ul><hr><h2 id="_2-guia-rapida-de-controles" tabindex="-1">2. Guía Rápida de Controles <a class="header-anchor" href="#_2-guia-rapida-de-controles" aria-label="Permalink to &quot;2. Guía Rápida de Controles&quot;">​</a></h2><p>El plugin cuenta con 4 perillas principales intuitivas y 3 selectores rotativos:</p><h3 id="🎛️-perillas-principales" tabindex="-1">🎛️ Perillas Principales <a class="header-anchor" href="#🎛️-perillas-principales" aria-label="Permalink to &quot;🎛️ Perillas Principales&quot;">​</a></h3><ul><li><strong>VOLUME / GAIN (<code>1.0</code> a <code>10.0</code>):</strong> Controla la ganancia de entrada. Ajustes bajos ofrecen un sonido limpio cristalino; niveles más altos entregan saturación valvular gruesa y sostenido cremoso.</li><li><strong>BASS (Filtro HP · <code>20 Hz</code> a <code>300 Hz</code>):</strong> Aprieta los graves y elimina frecuencias subgraves innecesarias, manteniendo las pistas rítmicas definidas.</li><li><strong>TONE (Filtro LP · <code>1.0 kHz</code> a <code>20.0 kHz</code>):</strong> Controla el brillo y suaviza asperezas agudas para un tono cálido y amaderado.</li><li><strong>MASTER (<code>1.0</code> a <code>10.0</code>):</strong> Nivel de salida limpio con hasta <code>+18 dB</code> de margen de volumen adicional.</li></ul><h3 id="🔀-selectores-e-interruptores" tabindex="-1">🔀 Selectores e Interruptores <a class="header-anchor" href="#🔀-selectores-e-interruptores" aria-label="Permalink to &quot;🔀 Selectores e Interruptores&quot;">​</a></h3><ul><li><strong>CHANNEL (Edge / Cranked):</strong><ul><li><strong>EDGE:</strong> Tono al borde de la ruptura (<em>edge-of-breakup</em>) con respuesta hiperdinámica al toque.</li><li><strong>CRANKED:</strong> Overdrive vintage rico y saturado con compresión densa de válvulas de potencia.</li></ul></li><li><strong>MIC / CAB (Respuestas de Gabinete IR):</strong><ul><li><strong>WARM:</strong> Micrófono de cinta Royer R121 para una respuesta suave y con mucho cuerpo.</li><li><strong>SHARP:</strong> Micrófono dinámico Shure SM57 con mordida y enfoque en medios-altos.</li><li><strong>BLEND:</strong> Combinación de estudio 60/40 (SM57 + R121) para profundidad y balance tridimensional.</li></ul></li><li><strong>STANDBY (Play / Mute):</strong> Silencia instantáneamente el audio y reduce el uso de CPU al <strong>0%</strong>.</li><li><strong>Fondo Personalizado:</strong> Arrastra y suelta cualquier archivo de imagen (<code>.jpg</code> o <code>.png</code>) directamente sobre la ventana del plugin para cambiar su aspecto al instante.</li></ul><hr><h2 id="_3-configuracion-de-audio-standalone" tabindex="-1">3. Configuración de Audio (Standalone) <a class="header-anchor" href="#_3-configuracion-de-audio-standalone" aria-label="Permalink to &quot;3. Configuración de Audio (Standalone)&quot;">​</a></h2><p>Cuando ejecutes el pedal como una aplicación independiente, configura tus ajustes de audio de la siguiente manera para un rendimiento óptimo:</p><ol><li><strong>Tipo de Dispositivo de Audio:</strong> Selecciona siempre <strong>ASIO</strong> en Windows para evitar latencia y distorsión digital.</li><li><strong>Dispositivo:</strong> Selecciona el controlador ASIO nativo de tu interfaz de audio (ej., <em>Focusrite USB ASIO</em>).</li><li><strong>Frecuencia de Muestreo (Sample Rate):</strong> Ajústalo a <strong>48000 Hz</strong> (48 kHz).</li><li><strong>Tamaño de Búfer (Buffer Size):</strong> Ajusta el tamaño del búfer a <strong>128 muestras</strong> (2.3 ms) o <strong>256 muestras</strong> (5.3 ms).</li></ol><h4 id="🎸-el-fenomeno-del-bufer-por-que-256-muestras-5-3-ms-podria-sonar-mejor-que-128-muestras-2-3-ms" tabindex="-1">🎸 El Fenómeno del Búfer: Por qué 256 muestras (5.3 ms) podría sonar mejor que 128 muestras (2.3 ms) <a class="header-anchor" href="#🎸-el-fenomeno-del-bufer-por-que-256-muestras-5-3-ms-podria-sonar-mejor-que-128-muestras-2-3-ms" aria-label="Permalink to &quot;🎸 El Fenómeno del Búfer: Por qué 256 muestras (5.3 ms) podría sonar mejor que 128 muestras (2.3 ms)&quot;">​</a></h4><p>Muchos guitarristas experimentan un tono más dulce y fluido a 256 muestras. Esto se debe a dos factores:</p><ul><li><strong>Estabilidad del Procesador:</strong> A 256 muestras, la CPU procesa bloques de audio con más margen, evitando micro fluctuaciones (jitters) que pueden introducir aspereza sutil en los agudos.</li><li><strong>Efecto de Duplicación Acústica:</strong> El diminuto retardo de 5.3 ms, combinado con el sonido acústico físico de tus cuerdas eléctricas desenchufadas vibrando en la habitación, crea un efecto orgánico de duplicación (doubling) que agrega profundidad tridimensional, grosor y una sensación natural de reverberación de sala a tu interpretación.</li></ul><hr><h2 id="_4-requisitos-del-sistema-y-distribucion" tabindex="-1">4. Requisitos del Sistema y Distribución <a class="header-anchor" href="#_4-requisitos-del-sistema-y-distribucion" aria-label="Permalink to &quot;4. Requisitos del Sistema y Distribución&quot;">​</a></h2><h3 id="requisitos-del-sistema" tabindex="-1">Requisitos del Sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del Sistema&quot;">​</a></h3><ul><li><strong>Sistemas Operativos</strong>: <ul><li><strong>Windows</strong>: Windows 10 o Windows 11 (64-bit).</li><li><strong>macOS</strong>: macOS 10.13 o más reciente (soporta de forma nativa Intel y Apple Silicon).</li><li><strong>Linux</strong>: Ubuntu 22.04 o distribución de 64-bit compatible.</li></ul></li><li><strong>Procesador (CPU)</strong>: Debe soportar instrucciones <strong>AVX2</strong> (Intel Core 4ª Generación / AMD Ryzen o más recientes) en Windows y Linux para calcular los modelos matemáticos en tiempo real. Los procesadores Apple Silicon son compatibles de forma nativa.</li><li><strong>RAM</strong>: 4 GB mínimo.</li><li><strong>Tarjeta de Audio (Modo Standalone)</strong>: Interfaz de audio con controladores de baja latencia (<strong>ASIO</strong> nativo en Windows; <strong>CoreAudio</strong> en macOS; <strong>JACK</strong> o <strong>ALSA</strong> en Linux).</li></ul><h3 id="distribucion-todo-en-uno" tabindex="-1">Distribución (Todo en Uno) <a class="header-anchor" href="#distribucion-todo-en-uno" aria-label="Permalink to &quot;Distribución (Todo en Uno)&quot;">​</a></h3><p><strong>Midnight Rambler es 100% autónomo.</strong> No requiere cargar modelos externos, configuraciones XML ni archivos IR por separado:</p><ul><li>Todos los modelos de amplificadores neuronales y perfiles de gabinetes están <strong>incrustados internamente como recursos binarios</strong> dentro del archivo del plugin.</li><li><strong>Windows</strong>: Simplemente copia el archivo <code>.vst3</code> en tu carpeta de plugins (usualmente <code>C:\\Program Files\\Common Files\\VST3\\</code>) o ejecuta la aplicación <code>.exe</code> (Standalone).</li><li><strong>macOS</strong>: Copia el <code>.vst3</code> o <code>.component</code> (AU) en tu carpeta de plugins (usualmente <code>/Library/Audio/Plug-Ins/VST3/</code> o <code>/Library/Audio/Plug-Ins/Components/</code>) o ejecuta la app <code>.app</code> (Standalone).</li><li><strong>Linux</strong>: Copia el archivo <code>.vst3</code> en tu carpeta de plugins (usualmente <code>~/.vst3/</code> o <code>/usr/lib/vst3/</code>) o ejecuta el binario independiente.</li></ul><hr><h2 id="_5-solucion-de-problemas-troubleshooting" tabindex="-1">5. Solución de Problemas (Troubleshooting) <a class="header-anchor" href="#_5-solucion-de-problemas-troubleshooting" aria-label="Permalink to &quot;5. Solución de Problemas (Troubleshooting)&quot;">​</a></h2><h3 id="el-vst3-no-aparece-en-el-daw-o-falla-al-escanear" tabindex="-1">El VST3 no aparece en el DAW o falla al escanear <a class="header-anchor" href="#el-vst3-no-aparece-en-el-daw-o-falla-al-escanear" aria-label="Permalink to &quot;El VST3 no aparece en el DAW o falla al escanear&quot;">​</a></h3><ul><li><strong>Falta C++ Redistributable (Windows)</strong>: Aunque el plugin está compilado estáticamente, algunas instalaciones de Windows pueden carecer de componentes de ejecución básicos. Descarga e instala el <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Microsoft Visual C++ Redistributable 2015-2022 (x64)</a> oficial.</li><li><strong>Compatibilidad de CPU (AVX2)</strong>: Asegúrate de que tu procesador soporte instrucciones <strong>AVX2</strong>. El motor neuronal subyacente NAM requiere AVX2 para calcular las redes neuronales en tiempo real en Windows y Linux. Si tu CPU carece de AVX2, el plugin no cargará.</li><li><strong>Ruta de Escaneo</strong>: Verifica que tu DAW esté escaneando la carpeta donde colocaste el archivo <code>.vst3</code>.</li></ul><h3 id="la-aplicacion-standalone-muestra-una-advertencia-de-desarrollador-no-identificado-macos" tabindex="-1">La aplicación Standalone muestra una advertencia de &quot;Desarrollador no identificado&quot; (macOS) <a class="header-anchor" href="#la-aplicacion-standalone-muestra-una-advertencia-de-desarrollador-no-identificado-macos" aria-label="Permalink to &quot;La aplicación Standalone muestra una advertencia de &quot;Desarrollador no identificado&quot; (macOS)&quot;">​</a></h3><ul><li><strong>Explicación</strong>: Debido a que los binarios del plugin se compilan mediante integración continua (CI) automatizada y no están notarizados con una Cuenta de Desarrollador de Apple paga, macOS puede evitar que se inicien.</li><li><strong>Solución</strong>: Ve a <strong>Configuración del Sistema &gt; Privacidad y Seguridad</strong>, desplázate hacia abajo hasta la sección de Seguridad y haz clic en <strong>Abrir de todos modos</strong> junto a la advertencia de Midnight Rambler. Como alternativa, abre Terminal y ejecuta: <code>xattr -cr /ruta/hacia/MidnightRambler.app</code></li></ul><h3 id="chasquidos-pops-o-alta-latencia-en-modo-standalone" tabindex="-1">Chasquidos, pops o alta latencia en modo Standalone <a class="header-anchor" href="#chasquidos-pops-o-alta-latencia-en-modo-standalone" aria-label="Permalink to &quot;Chasquidos, pops o alta latencia en modo Standalone&quot;">​</a></h3><ul><li><strong>Controladores de Audio (Drivers)</strong>: Asegúrate de estar usando el controlador nativo de baja latencia para tu interfaz de audio (<strong>ASIO</strong> en Windows, <strong>CoreAudio</strong> en macOS, <strong>JACK</strong> o <strong>ALSA</strong> en Linux).</li><li><strong>Tamaño del Búfer</strong>: Se recomienda un tamaño de búfer de <strong>128</strong> o <strong>256 muestras</strong>. Reducirlo a menos de 64 muestras puede causar picos de CPU y crujidos en el audio dependiendo del rendimiento de tu computadora.</li></ul><hr><h2 id="_6-licencia-y-terminos-de-uso" tabindex="-1">6. Licencia y Términos de Uso <a class="header-anchor" href="#_6-licencia-y-terminos-de-uso" aria-label="Permalink to &quot;6. Licencia y Términos de Uso&quot;">​</a></h2><p><strong>Midnight Rambler</strong> se distribuye como <strong>Freeware (Código Cerrado)</strong> bajo el <a href="/LICENSE.txt">Acuerdo de Licencia de Usuario Final (EULA) de Main St Audio Labs</a>:</p><ul><li><strong>Uso Gratuito:</strong> Sos 100% libre de usar este plugin en cualquier producción musical personal, educativa o comercial, mezcla o actuación en vivo sin pagar ningún tipo de regalía o licencia.</li><li><strong>Protección de Código Cerrado:</strong> Queda estrictamente prohibida la ingeniería inversa, descompilación, reventa o cobro por la descarga de los archivos binarios del software. Todos los derechos de propiedad intelectual pertenecen exclusivamente a <em>Main St Audio Labs</em>.</li><li><strong>Exención de Responsabilidad:</strong> El software se proporciona &quot;TAL CUAL&quot; (&quot;AS IS&quot;), sin garantías de ningún tipo. Los nombres de marcas registradas de terceros (<em>Fender</em>, <em>Tweed Deluxe</em>, <em>5E3</em>, etc.) se utilizan únicamente con fines descriptivos e históricos para identificar el tono del equipo emulado.</li></ul><hr><h3 id="¡queremos-escuchar-tus-mezclas" tabindex="-1">¡Queremos escuchar tus mezclas! <a class="header-anchor" href="#¡queremos-escuchar-tus-mezclas" aria-label="Permalink to &quot;¡Queremos escuchar tus mezclas!&quot;">​</a></h3><p>El comportamiento dinámico de Midnight Rambler se calibró directamente a partir de pruebas de audición de discos clásicos. Si has grabado una canción o mezclado una pista usando este pedal, ¡queremos escucharla!</p><p>Copia nuestro correo electrónico de contacto para compartir tus enlaces o comentarios:</p>',47)),a("div",d,[e[0]||(e[0]=a("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),a("button",{class:"rock-copy-btn",onClick:i},t(o.value),1)]),e[2]||(e[2]=a("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"Si deseas apoyar nuestra investigación independiente y ayudarnos a mantener nuestros plugins gratuitos, puedes apoyarnos con Tarjeta, PayPal o Criptomonedas:",-1)),e[3]||(e[3]=a("div",null,[a("a",{href:"/es/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Apoya el Laboratorio (Ko-fi / Crypto) ☕")],-1))]))}});export{g as __pageData,b as default};
